from ledger.tax._rule_table import JURISDICTIONS, RULES
CODES = ("S", "R", "Z", "E")
@dataclass(frozen=True)
class TaxRule:
    jurisdiction: str
    code: str
    effective_from: date
    rate: Decimal
    def describe(self) -> str:
